-- bench.lua — Lua engine benchmark for the SPIComputer OS.
--
-- Launch from the shell:  bench
--
-- Runs one timed test per tick (so the scheduler keeps feeding the
-- watchdog between them), shows the results on screen and writes them
-- to /data/bench.txt so they can be read off the card. Iteration counts
-- are fixed, so a result is comparable across firmware builds: the
-- numbers to watch are ops/ms per test and the GC stall time. Take a
-- run before and after any change to the Lua build (number types, the
-- interpreter's placement, GC settings) and compare the two files.
--
-- Built from the SPIEdit project in this folder: edit the components
-- here and Build, or run `swift run --package-path ide/macos spibuild
-- software/bench` from the workspace root. The app bundle is written to
-- software/apps/bench.app.

-- ==== component: tests (lua) ====

-- Each test is { name, ops, fn }: fn runs a fixed amount of work and
-- returns a checksum (kept so the interpreter cannot drop the loop).
-- `ops` is the number of operations the test counts as, for the
-- ops/ms figure. Names fit the 14-column label on screen.
--
-- Sizes are chosen to take 100-500 ms each on the board at 252 MHz;
-- the whole set stays well inside the 2 s watchdog per tick.

local N_INT = 200000
local N_FLOAT = 200000
local N_CALL = 200000
-- Live-set sizes are held well under the per-program heap cap: an array grows
-- by doubling (old and new blocks coexist during the realloc) and the
-- previous rep's table is still garbage while the next one fills.
local N_ARRAY = 1000       -- 1000 numbers = 16 KB of TValues at 16 B
local N_ARRAY_REPS = 40
local N_HASH = 250
local N_HASH_REPS = 40
local N_STRING = 3000
local N_API = 50000
local N_API_TABLE = 20000
-- Kept under the 1024-op display queue (with the screen redraw's own
-- ops): a full queue blocks until core 0's next frame drain on the
-- board and, because the simulator is single-threaded, hangs it.
local N_SCREEN = 600

tests = {}

local function add(name, ops, fn)
    tests[#tests + 1] = { name = name, ops = ops, fn = fn }
end

-- Integer arithmetic in a tight loop (the common case in game code).
add("int loop", N_INT, function()
    local s = 0
    for i = 1, N_INT do
        s = s + (i * 3) % 7
    end
    return s
end)

-- Float arithmetic: double soft-float today, single after LUA_32BITS.
add("float loop", N_FLOAT, function()
    local x = 1.5
    for i = 1, N_FLOAT do
        x = x * 1.000001 + 0.25
        if x > 1e6 then x = x - 1e6 end
    end
    return math.floor(x)
end)

-- Lua-to-Lua calls: frame overhead of the VM.
add("lua call", N_CALL, function()
    local function f(a, b)
        return a + b
    end
    local s = 0
    for i = 1, N_CALL do
        s = f(s, i)
    end
    return s
end)

-- Array part: fill and read back; each rep allocates a fresh table so
-- the collector has to work (this is what a small heap cap makes expensive).
add("table array", N_ARRAY * N_ARRAY_REPS * 2, function()
    local s = 0
    for _ = 1, N_ARRAY_REPS do
        local t = {}
        for i = 1, N_ARRAY do
            t[i] = i
        end
        for i = 1, N_ARRAY do
            s = s + t[i]
        end
    end
    return s
end)

-- Hash part with string keys: interning plus hashing plus lookup.
add("table hash", N_HASH * N_HASH_REPS * 2, function()
    local s = 0
    for _ = 1, N_HASH_REPS do
        local t = {}
        for i = 1, N_HASH do
            t["k" .. i] = i
        end
        for i = 1, N_HASH do
            s = s + t["k" .. i]
        end
    end
    return s
end)

-- String building and scanning, the text-heavy path (shell, editor).
add("string ops", N_STRING, function()
    local s = 0
    local base = string.rep("abcdefgh", 25) -- 200 chars
    for i = 1, N_STRING do
        local line = base:sub(1 + (i % 100), 40 + (i % 100)) .. i
        s = s + line:byte(1) + #line
    end
    return s
end)

-- C API call with no result table: the OS call overhead itself
-- (argument checks plus finding the program from the Lua state).
add("api TimeNow", N_API, function()
    local s = 0
    for _ = 1, N_API do
        s = s + TimeNow()
    end
    return s
end)

-- C API call that returns a table per call: allocation on the hot path.
add("api InputCtl", N_API_TABLE, function()
    local s = 0
    for _ = 1, N_API_TABLE do
        local c = InputControl(1)
        if c.fire then s = s + 1 end
    end
    return s
end)

-- The per-cell display call: argument checks plus one queued op each.
-- Row 28 is scratch.
add("ScreenOut", N_SCREEN, function()
    for i = 0, N_SCREEN - 1 do
        ScreenOut(i % 40, 28, 32 + (i % 64), 0)
    end
    return 0
end)

-- A full collection with a live set of a hundred small tables (~15 KB
-- on the board, more on a 64-bit host): the stall a game would see if
-- the collector runs mid-frame.
add("gc full", 1, function()
    local live = {}
    for i = 1, 100 do
        live[i] = { i, i * 2, name = "obj" .. i }
    end
    collectgarbage("collect")
    local t0 = TimeNow()
    collectgarbage("collect")
    gc_stall_ms = TimeNow() - t0
    return #live
end)

-- ==== component: main (lua) ====

local COLS = 40
local results = {}        -- { name, ms, ops_per_ms }
local next_test = 1
local finished = false

local function text(x, row, message, attr)
    for i = 1, math.min(#message, COLS - x) do
        ScreenOut(x + i - 1, row, message:byte(i), attr or 0)
    end
end

-- Describe the Lua build in one line: the integer width and float
-- precision tell you whether LUA_32BITS is in effect.
local function build_line()
    local bits = math.maxinteger > 2147483647 and 64 or 32
    local fbits = (2 ^ 24 + 1 == 2 ^ 24) and 32 or 64
    return string.format("%s int%d float%d", _VERSION, bits, fbits)
end

local function result_line(r)
    return string.format("%-14s %6dms %8d/ms", r.name, r.ms, r.ops_per_ms)
end

local function draw()
    ScreenClear(32)
    text(0, 0, "SPICOMPUTER LUA BENCHMARK", 0x80)
    text(0, 1, build_line(), 0)
    text(0, 3, string.format("%-14s %8s %11s", "test", "time", "rate"), 0x02)
    for i, r in ipairs(results) do
        text(0, 3 + i, result_line(r), 0)
    end
    if finished then
        text(0, 5 + #results, string.format("gc full stall  %6dms", gc_stall_ms or 0), 0)
        text(0, 6 + #results, "saved to /data/bench.txt", 0x02)
        text(0, 7 + #results, "! = hit the heap cap (see file)", 0x02)
        text(0, 9 + #results, "press any key to exit", 0x80)
    elseif next_test <= #tests then
        text(0, 4 + #results, "running " .. tests[next_test].name .. "...", 0x02)
    end
end

local function save()
    local lines = { build_line(), "test,ms,ops_per_ms" }
    for _, r in ipairs(results) do
        lines[#lines + 1] = string.format("%s,%d,%d%s", r.name, r.ms,
                                          r.ops_per_ms,
                                          r.err and ("," .. r.err) or "")
    end
    lines[#lines + 1] = string.format("gc full stall,%d,0", gc_stall_ms or 0)
    fs.writeall("/data/bench.txt", table.concat(lines, "\n") .. "\n")
end

function setup()
    ScreenMode(1)
    draw()
end

-- One test per tick: the scheduler feeds the watchdog between ticks,
-- and each test is sized to stay well under its 2 s period.
function tick()
    if finished then
        return
    end
    local t = tests[next_test]
    if not t then
        finished = true
        save()
        draw()
        return
    end
    collectgarbage("collect") -- start each test with a clean heap
    local t0 = TimeNow()
    local ok, err = pcall(t.fn)
    local ms = TimeNow() - t0
    -- A test that runs out of heap is a result too (the cap, not the
    -- VM, is what it measured): record it as a zero rate.
    results[#results + 1] = {
        name = ok and t.name or (t.name .. "!"),
        ms = ms,
        ops_per_ms = (ok and ms > 0) and math.floor(t.ops / ms)
                     or (ok and t.ops or 0),
        err = not ok and tostring(err) or nil,
    }
    next_test = next_test + 1
    draw()
end

function on_keypress()
    if finished then
        ExitProgram()
    end
end

-- ==== generated: asset helper ====

-- Runs every asset component (tiles, palettes, sounds, scores).
-- Called from setup(); safe to call more than once.
function ApplyAssets()
    if __spi_assets then
        for _, apply in ipairs(__spi_assets) do
            apply()
        end
    end
end
